import { revalidateTag } from 'next/cache'
import { getProducts, PRODUCTS_TAG } from '@/lib/products'

export default async function AdminProductCatalogPage() {
  const products = await getProducts()

  async function syncCatalog() {
    'use server'

    // In production this would enqueue/kick off the ERP/PIM sync job here.
    //
    // Stale-while-revalidate: mark the "products" tag stale so every view
    // using it refetches in the background, while the action returns
    // immediately and readers keep getting the (briefly stale) cached list.
    // updateTag() would instead expire the entry and block this response on
    // a fresh recompute — wrong trade-off for thousand-SKU sync jobs.
    revalidateTag(PRODUCTS_TAG, 'max')
  }

  return (
    <main>
      <h1>Product Catalog</h1>

      <form action={syncCatalog}>
        <button type="submit">Sync latest catalog</button>
      </form>

      <table>
        <thead>
          <tr>
            <th>ID</th>
            <th>Name</th>
            <th>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td>{product.id}</td>
              <td>{product.name}</td>
              <td>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

